import java.net.*;import java.nio.file.*;
public class Items710ServerCheck {
 static void ok(boolean b,String s){if(!b)throw new AssertionError(s);System.out.println("PASS: "+s);}
 static final class Flat implements Battle.Ground {int holes;public boolean solid(int x,int y){return y>=170;}public int surface(int x,int y){return Math.max(y,170);}public void crater(int x,int y,int r){holes++;}}
 static Battle fresh(){Battle b=new Battle(new Flat());b.start(true);return b;}static void kit(Battle.Unit u,int a,int b,int c){u.kit[0]=a;u.kit[1]=b;u.kit[2]=c;}
 static void rules(){Battle b=fresh();Battle.Unit u=b.units[0];ok(u.heals==5,"Heal buff starts with five uses");for(int i=0;i<5;i++){u.hp=1000;u.energy=240;ok(b.prop(3)&&u.hp==1500,"R heals 500 at 150 energy");}u.energy=240;u.hp=1000;ok(!b.prop(3)&&u.heals==0,"Sixth heal is rejected");b=fresh();u=b.units[0];ok(b.prop(4)&&u.flyCooldown==3&&u.energy==90,"Plane buff costs 150 and starts cooldown");ok(Battle.minLocalAngle(u)==0&&Battle.maxLocalAngle(u)==90,"Plane supports angles outside weapon limits");b.next();b.next();ok(u.flyCooldown==2&&!b.prop(4),"Plane blocked on first following own turn");b.next();b.next();ok(u.flyCooldown==1&&!b.prop(4),"Plane blocked on second following own turn");b.next();b.next();ok(b.prop(4),"Plane returns after two complete own turns");
 b=fresh();u=b.units[0];ok(b.item(0)&&u.invisible==2&&u.energy==190,"Invisibility costs 50 and starts immediately");b.next();ok(u.invisible==1,"First invisible own turn completed");b.next();ok(u.invisible==1,"Still invisible on second own turn");b.next();ok(u.invisible==0,"Visible after two own turns");b.next();ok(!b.item(0)&&u.itemUsed==1,"Item remains consumed for the whole match");
 b=fresh();b.configureTeam(2);u=b.units[0];kit(u,2,3,5);u.hp=1000;b.units[2].hp=1200;b.units[1].hp=1000;ok(b.item(0)&&u.hp==1300&&b.units[2].hp==1500&&b.units[1].hp==1000&&u.energy==70,"Group heal uses native 170 energy and heals allies by 300");u.energy=240;ok(b.item(1)&&u.invisible==2&&b.units[2].invisible==2&&b.units[1].invisible==0&&u.energy==90,"Group invisibility costs 150 and affects own team only");u.energy=240;u.rage=20;ok(b.item(2)&&u.rage==70&&u.energy==120,"Rage item adds 50 rage at 120 energy");
 b=fresh();u=b.units[0];kit(u,1,4,5);ok(b.item(0)&&b.freezeShot&&u.energy==90,"Ice costs 150 and arms its own throw");ok(!b.prop(0)&&!b.prop(1)&&!b.prop(2),"Ice throw cannot stack weapon multishot/damage buffs");Battle.Ball ice=b.make(45,60);ice.x=b.units[1].x*256;ice.y=(b.units[1].y-12)*256;b.impact(ice);ok(b.units[1].freezeTurns==2&&b.units[1].hp==Battle.MAXHP&&((Flat)b.ground).holes==0,"Ice locks target without damaging HP or destroying terrain");b.next();ok(b.units[1].frozen==2&&!b.input(),"Frozen target cannot act");for(int i=0;i<30;i++)b.tick();ok(b.active==0&&b.units[1].freezeTurns==1,"First frozen turn skipped");b.next();for(int i=0;i<30;i++)b.tick();ok(b.active==0&&b.units[1].freezeTurns==0,"Second frozen turn skipped and effect ends");
 Battle.Ball hit=b.make(45,60);hit.x=b.units[1].x*256;hit.y=(b.units[1].y-12)*256;int hp=b.units[1].hp;b.units[1].freezeTurns=2;b.units[1].frozen=1;b.impact(hit);ok(b.units[1].freezeTurns==0&&b.units[1].hp==hp-hit.damage/2,"A real attack breaks ice and halves the breaking hit damage");
 b=fresh();u=b.units[0];kit(u,4,0,5);Battle.Ball normal=b.make(45,60);ok(b.item(0)&&u.energy==120,"Guidance costs 120");Battle.Ball guided=b.make(45,60);ok(guided.guided&&guided.damage==normal.damage/2,"Guidance reduces weapon damage by 50 percent");guided.x=(b.units[1].x-30)*256;guided.y=(b.units[1].y-45)*256;guided.vx=1500;guided.vy=0;b.guide(guided);ok(guided.vy>0,"Nearby guided projectile actually bends toward enemy");guided.x=0;guided.y=0;int vx=guided.vx,vy=guided.vy;b.guide(guided);ok(guided.vx==vx&&guided.vy==vy,"Guidance does not lock a target outside the 100px range");b=fresh();u=b.units[0];u.rage=100;ok(b.prop(5)&&u.rage==0&&b.pow,"POW still consumes full rage");b.start(true);ok(b.units[0].itemUsed==0&&b.units[0].heals==5&&b.units[0].flyCooldown==0,"New match replenishes items, heal count and cooldown");}
 public static void main(String[] a)throws Exception{rules();CloudStore.Memory store=new CloudStore.Memory();try(GunnyServer server=new GunnyServer(new InetSocketAddress("127.0.0.1",0),Path.of("backend/assets"),store)){var host=Matchmaking680Check.person(store,70);host.items=true;host.itemVersion=2;kitSession(host,0,1,4);var enemy=Matchmaking680Check.person(store,71);enemy.items=true;enemy.itemVersion=2;var r=Matchmaking680Check.room(server,host,null);r.members[1]=enemy;enemy.room=r.id;enemy.armed=true;r.refreshWaiting();r.start();r.phase=1;r.battle.explicitHumans=true;r.battle.units[0].human=true;r.command(host,1,8,0);ok(r.battle.units[0].invisible==2&&r.battle.units[0].energy==190,"Server independently charges and executes invisibility");r.command(host,2,8,0);ok(r.battle.units[0].energy==190,"Duplicate item attempt is rejected");r.battle.units[0].energy=0;r.command(host,3,8,1);ok(!r.battle.freezeShot,"Server rejects unaffordable ice");r.chunkFrame();r.chunkFlush(false);ok(!r.chunks.isEmpty(),"New status extension is captured inside buffered chunks");}System.out.println("All item 7.1.0 server checks passed");}static void kitSession(GunnyServer.Session s,int a,int b,int c){s.kit[0]=a;s.kit[1]=b;s.kit[2]=c;}
}
